"""Optional causal error memory; unchanged perception/retrieval/confirmation."""
import json
import math
import struct

from tools._s2uc_signal_approx_adapter import SignalApproxAdapter
from tools._s2uc_pair_context_adapter import AdapterError, PerceptionSample

CELL = struct.Struct('<QddBBBB4x')  # generation, errors, role, offset, quality, valid
TICKET = struct.Struct('<QQBBBBB11x')  # generation, target, role, offset, quality, choice, valid
CELLS = 12


def require(ok, code):
    if not ok:
        raise AdapterError(code)


def mae48(x, y):
    """Shared internal/baseline arithmetic: ordered scalar binary64 additions."""
    require(type(x) is tuple and type(y) is tuple and len(x)==len(y)==48, 'MAE_SHAPE')
    total = 0.0
    for i in range(48):
        require(type(x[i]) is float and type(y[i]) is float and math.isfinite(x[i]) and math.isfinite(y[i]), 'MAE_VALUES')
        difference = abs(x[i]-y[i])
        total = total+difference
        require(math.isfinite(difference) and math.isfinite(total), 'MAE_NONFINITE')
    return total/48.0


class ErrorMemory:
    __slots__ = ('cells','ticket')

    def __init__(self):
        self.cells = bytearray(CELLS*CELL.size)
        self.ticket = bytearray(TICKET.size)

    def clear(self):
        self.cells[:] = bytes(CELLS*CELL.size)
        self.release()

    def release(self):
        self.ticket[:] = bytes(TICKET.size)

    def find(self, role, generation, offset, quality):
        for i in range(CELLS):
            g, ec, ep, r, o, q, valid = CELL.unpack_from(self.cells, i*CELL.size)
            if valid and (r,g,o,q)==(role,generation,offset,quality):
                return i
        return None

    def errors(self, role, generation, offset, quality):
        i = self.find(role,generation,offset,quality)
        if i is None:
            return None
        row = CELL.unpack_from(self.cells,i*CELL.size)
        return row[1],row[2]

    def prepare(self, role, generation, offset, quality, target):
        require(role in (0,1) and offset in (0,1) and quality in (0,1), 'EMA_KEY')
        require(type(generation) is int and 0<generation<2**64 and type(target) is int and 0<target<2**63, 'EMA_GENERATION')
        require(not TICKET.unpack(self.ticket)[-1], 'EMA_TICKET_PENDING')
        errors = self.errors(role,generation,offset,quality)
        choice = int(errors is not None and errors[0]<errors[1])
        TICKET.pack_into(self.ticket,0,generation,target,role,offset,quality,choice,1)

    def update(self, role, generation, offset, quality, ec, ep):
        require(all(type(x) is float and math.isfinite(x) and x>=0 for x in (ec,ep)), 'EMA_ERROR_VALUES')
        i = self.find(role,generation,offset,quality)
        if i is None:
            for j in range(CELLS):
                if not CELL.unpack_from(self.cells,j*CELL.size)[-1]:
                    i=j
                    break
            require(i is not None,'EMA_CELL_LIMIT')
        else:
            old=CELL.unpack_from(self.cells,i*CELL.size)
            ec=(0.5*old[1])+(0.5*ec)
            ep=(0.5*old[2])+(0.5*ep)
        require(math.isfinite(ec) and math.isfinite(ep),'EMA_NONFINITE')
        # Build all bytes before publication: conversion/packing cannot partially commit.
        packed=CELL.pack(generation,ec,ep,role,offset,quality,1)
        self.cells[i*CELL.size:(i+1)*CELL.size]=packed

    def prune(self, adapter):
        for i in range(CELLS):
            generation,_,_,role,_,_,valid=CELL.unpack_from(self.cells,i*CELL.size)
            if valid and not adapter._generation_live(role,generation):
                self.cells[i*CELL.size:(i+1)*CELL.size]=bytes(CELL.size)


class PairedErrorAdapter(SignalApproxAdapter):
    """Disabled unless selection_policy is explicitly paired_error_ema_v1.

    Active callers consume_feedback(valid next sample) before normal admission.
    Output selection is an alias; original context and persistence stay frozen.
    """
    def __setattr__(self,name,value):
        if name in ('selection_policy','_selection_policy') and hasattr(self,'_selection_policy'):
            raise AdapterError('SELECTION_POLICY_IMMUTABLE')
        super().__setattr__(name,value)

    def __delattr__(self,name):
        if name in ('selection_policy','_selection_policy'):
            raise AdapterError('SELECTION_POLICY_IMMUTABLE')
        super().__delattr__(name)

    @property
    def selection_policy(self):
        return self._selection_policy

    def __init__(self,*args,selection_policy='disabled',**kwargs):
        require(selection_policy in ('disabled','paired_error_ema_v1'),'SELECTION_POLICY')
        require(kwargs.get('policy','legacy_v1')=='legacy_v1','EMA_LEGACY_ONLY')
        self._selection_policy=selection_policy
        self._errors=None
        self._feedback_scope=None
        super().__init__(*args,**kwargs)
        if selection_policy=='paired_error_ema_v1':
            require(all(0<=x<2**63 for x in (self.hop,self.window,self.start_sample,self.first_ordinal)), 'EMA_TIME_RANGE')
            self._errors=ErrorMemory()
            self._feedback_scope=(self.arm.owner,self.arm.profile,self.stream,self.hop,self.window,self.start_sample,self.first_ordinal)

    def _generation_live(self,role,generation):
        if role==0:
            return any(t.generation==generation for t in self.arm._retained_many)
        return self.arm._candidate is not None and self.arm._candidate.candidate_generation==generation

    def _validate_feedback_input(self,sample):
        require(not self.closed,'CLOSED')
        require(type(sample) is PerceptionSample,'PERCEPTION_TYPE_REQUIRED')
        require(self._feedback_scope==(self.arm.owner,self.arm.profile,self.stream,self.hop,self.window,self.start_sample,self.first_ordinal),'SCOPE_CHANGED')
        i=sample.index
        require(type(i) is int and i==self.next_index and 1<=i<2**63,'INDEX_GAP_OR_REORDER')
        require((sample.profile,sample.owner,sample.stream)==(self.arm.profile,self.arm.owner,self.stream),'SCOPE_CHANGED')
        start=self.start_sample+(i-1)*self.hop
        require(type(sample.start_sample) is int and type(sample.end_sample) is int and
                (sample.start_sample,sample.end_sample)==(start,start+self.window),'TIME_DISCONTINUITY')
        require(0<=sample.start_sample<sample.end_sample<2**63,'EMA_TIME_RANGE')
        require(type(sample.values) is tuple and len(sample.values)==48 and
                all(type(x) is float and math.isfinite(x) for x in sample.values),'VALUES_INVALID')
        require(self.first_ordinal+i-1<2**63,'ORDINAL_LIMIT')

    def _freeze_choice(self):
        p=self.pending_prediction
        if p is None or p.context_values is None:
            return
        data=json.loads(p.provenance_json)
        require(len(data['matches'])==1,'EMA_SINGLE_REQUIRED')
        match=data['matches'][0]
        role={'retained':0,'candidate':1}[match['role']]
        quality={'EXACT':0,'APPROXIMATE':1}[match.get('match_quality','EXACT')]
        self._errors.prepare(role,match['generation'],match['offset'],quality,p.target_index)

    def _receipt(self,status,indices,intervals,matches):
        receipt=super()._receipt(status,indices,intervals,matches)
        if self._errors is not None and len(indices)==2:
            self._errors.prune(self)
            self._freeze_choice()
        return receipt

    @property
    def selected_values(self):
        p=self.pending_prediction
        if p is None:
            return None
        if self._errors is None:
            return p.context_values if p.context_values is not None else p.persistence_values
        row=TICKET.unpack(self._errors.ticket)
        return p.context_values if row[-1] and row[-2] else p.persistence_values

    def consume_feedback(self,sample):
        try:
            require(self._errors is not None,'EMA_NOT_ENABLED')
            self._validate_feedback_input(sample)
            p=self.pending_prediction
            require(p is not None and p.target_index==sample.index,'PREDICTION_TARGET_INVALID')
            generation,target,role,offset,quality,choice,valid=TICKET.unpack(self._errors.ticket)
            if valid:
                require(target==sample.index and p.context_values is not None,'EMA_TICKET_TARGET')
                ec=mae48(p.context_values,sample.values)
                ep=mae48(p.persistence_values,sample.values)
                if self._generation_live(role,generation):
                    self._errors.update(role,generation,offset,quality,ec,ep)
        except Exception:
            self._terminate()
            raise
        finally:
            self.release_prediction()

    def accept_perception(self,sample):
        if self._errors is not None:
            try:
                self._validate_feedback_input(sample)
            except Exception:
                self._terminate()
                raise
        return super().accept_perception(sample)

    def _admit(self,frame):
        super()._admit(frame)
        if self._errors is not None:
            self._errors.prune(self)

    def release_prediction(self):
        super().release_prediction()
        if self._errors is not None:
            self._errors.release()

    def _terminate(self):
        if self._errors is not None:
            self._errors.clear()
        super()._terminate()

    def finish_story(self):
        # An even-length bounded story can leave one unobserved next target.
        if self._errors is not None:
            self.release_prediction()
        return super().finish_story()

tools/_s2uc_provisional_hint.py:
"""B2-V: only hint retrieval changes; no additional memory state."""
from tools._s2uc_four_arm import CandidateTwoArm, tu


class ProvisionalHintArm(CandidateTwoArm):
    def hint(self, frame):
        self._check(frame)
        if self._hints:
            tu.need(frame.segment == self._hint_segment and frame.ordinal > self._hints[-1].ordinal,
                    'HINT_ORDER_INVALID')
        else:
            self._hint_segment = frame.segment
        tu.need(len(self._hints) < 2, 'HINT_BUFFER_INVALID')
        self._hints.append(frame)
        if len(self._hints) == 1:
            self._check_budget()
            return None
        hint = tuple(self._hints)
        self._hints.clear()
        self._hint_segment = None
        matches = []
        sources = [('retained', trace.generation, trace.frames) for trace in self._retained_many]
        if self._candidate is not None:
            sources.append(('candidate', self._candidate.candidate_generation, self._candidate.frames))
        for role, generation, frames in sources:
            for offset in range(3):
                if frames[offset].values == hint[0].values and frames[offset+1].values == hint[1].values:
                    matches.append(dict(role=role, generation=generation, formation=frames[0].segment,
                                        ordinals=[f.ordinal for f in frames], offset=offset))
        decision = ('ABSTAIN_NO_MATCH' if not matches else 'ABSTAIN_AMBIGUOUS' if len(matches) > 1
                    else 'PROVISIONAL_CANDIDATE_MATCH' if matches[0]['role'] == 'candidate'
                    else 'CONFIRMED_RETAINED_MATCH')
        self._check_budget()
        return dict(decision=decision, matches=matches)

tools/_s2uc_record_codec.py:
"""Lossless, versioned S2-UC record codecs; V1 remains readable."""
from __future__ import annotations

import json
import math
import struct

from tools import _s2tu_retained_trace as tu


VERSION = "s2uc.record-codec.v3"
PREVIOUS_VERSION = "s2uc.record-codec.v2"
LEGACY_VERSION = "s2uc.record-codec.v1"


def _bits(value: float) -> bytes:
    return struct.pack(">d", value)


def _vector_from_values_hex(value) -> tuple[bytes, ...] | None:
    """Accept only the canonical finite representation emitted by `_hex`."""
    if type(value) is not list or len(value) != 48 or not all(type(item) is str for item in value):
        return None
    try:
        values = tuple(float.fromhex(item) for item in value)
    except ValueError:
        return None
    if not all(math.isfinite(item) and item.hex() == text for item, text in zip(values, value, strict=True)):
        return None
    return tuple(_bits(item) for item in values)


def _vector_index(key, vectors, vector_indexes) -> int:
    index = vector_indexes.setdefault(key, len(vectors))
    if index == len(vectors):
        vectors.append({"values_bits": [item.hex() for item in key]})
    return index


def _encode_v2(value, frames, frame_indexes, vectors, vector_indexes):
    if isinstance(value, tu.Frame):
        vector_key = tuple(_bits(item) for item in value.values)
        vector_index = _vector_index(vector_key, vectors, vector_indexes)
        frame_key = (vector_index, value.profile, value.owner, value.segment, value.ordinal)
        frame_index = frame_indexes.setdefault(frame_key, len(frames))
        if frame_index == len(frames):
            frames.append({"vector": vector_index, "profile": value.profile, "owner": value.owner,
                           "segment": value.segment, "ordinal": value.ordinal})
        return {"@frame": frame_index}
    if isinstance(value, tuple):
        return {"@tuple": [_encode_v2(item, frames, frame_indexes, vectors, vector_indexes) for item in value]}
    if isinstance(value, list):
        return [_encode_v2(item, frames, frame_indexes, vectors, vector_indexes) for item in value]
    if isinstance(value, dict):
        encoded = {}
        for key, item in value.items():
            values_hex = _vector_from_values_hex(item) if key == "values_hex" else None
            encoded[key] = {"@values_hex": _vector_index(values_hex, vectors, vector_indexes)} if values_hex is not None else _encode_v2(item, frames, frame_indexes, vectors, vector_indexes)
        return encoded
    return value


def _decode(value, frames, vectors):
    if isinstance(value, list):
        return [_decode(item, frames, vectors) for item in value]
    if not isinstance(value, dict):
        return value
    if set(value) == {"@tuple"}:
        return tuple(_decode(item, frames, vectors) for item in value["@tuple"])
    if set(value) == {"@frame"}:
        index = value["@frame"]
        if type(index) is not int or not 0 <= index < len(frames):
            raise ValueError("RECORD_FRAME_REFERENCE_INVALID")
        return frames[index]
    if set(value) == {"@values_hex"}:
        index = value["@values_hex"]
        if type(index) is not int or not 0 <= index < len(vectors):
            raise ValueError("RECORD_VECTOR_REFERENCE_INVALID")
        return [item.hex() for item in vectors[index]]
    return {key: _decode(item, frames, vectors) for key, item in value.items()}


def dumps(record: dict[str, object]) -> bytes:
    frames, frame_indexes, vectors, vector_indexes = [], {}, [], {}
    encoded = _encode_v2(record, frames, frame_indexes, vectors, vector_indexes)
    return json.dumps({"version": VERSION, "vectors": vectors, "frames": frames, "record": encoded},
                      allow_nan=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _loads_v1(value: dict[str, object]) -> dict[str, object]:
    if set(value) != {"version", "frames", "record"} or type(value["frames"]) is not list:
        raise ValueError("RECORD_CODEC_INVALID")
    frames = [tu.Frame(tuple(float.fromhex(item) for item in frame["values_hex"]), frame["profile"], frame["owner"],
                       frame["segment"], frame["ordinal"]) for frame in value["frames"]]
    return _decode(value["record"], frames, [])


def _loads_vectors(value: dict[str, object], *, permit_values_hex: bool) -> dict[str, object]:
    if set(value) != {"version", "vectors", "frames", "record"} or type(value["vectors"]) is not list or type(value["frames"]) is not list:
        raise ValueError("RECORD_CODEC_INVALID")
    vectors = []
    for vector in value["vectors"]:
        if type(vector) is not dict or set(vector) != {"values_bits"} or type(vector["values_bits"]) is not list or len(vector["values_bits"]) != 48:
            raise ValueError("RECORD_VECTOR_INVALID")
        try:
            values = tuple(struct.unpack(">d", bytes.fromhex(item))[0] for item in vector["values_bits"])
        except (TypeError, ValueError, struct.error) as exc:
            raise ValueError("RECORD_VECTOR_INVALID") from exc
        vectors.append(values)
    frames = []
    for frame in value["frames"]:
        if type(frame) is not dict or set(frame) != {"vector", "profile", "owner", "segment", "ordinal"}:
            raise ValueError("RECORD_FRAME_INVALID")
        index = frame["vector"]
        if type(index) is not int or not 0 <= index < len(vectors):
            raise ValueError("RECORD_VECTOR_REFERENCE_INVALID")
        frames.append(tu.Frame(vectors[index], frame["profile"], frame["owner"], frame["segment"], frame["ordinal"]))
    decoded = _decode(value["record"], frames, vectors)
    if not permit_values_hex:
        def reject_values_hex(item):
            if isinstance(item, dict):
                if set(item) == {"@values_hex"}:
                    raise ValueError("RECORD_CODEC_INVALID")
                for nested in item.values(): reject_values_hex(nested)
            elif isinstance(item, list):
                for nested in item: reject_values_hex(nested)
        reject_values_hex(value["record"])
    return decoded


def loads(data: bytes) -> dict[str, object]:
    value = json.loads(data)
    if type(value) is not dict:
        raise ValueError("RECORD_CODEC_INVALID")
    if value.get("version") == LEGACY_VERSION:
        decoded = _loads_v1(value)
    elif value.get("version") == PREVIOUS_VERSION:
        decoded = _loads_vectors(value, permit_values_hex=False)
    elif value.get("version") == VERSION:
        decoded = _loads_vectors(value, permit_values_hex=True)
    else:
        raise ValueError("RECORD_CODEC_INVALID")
    if type(decoded) is not dict:
        raise ValueError("RECORD_CODEC_INVALID")
    return decoded


def estimate_worst_case(*, frame_count: int, record_metadata_bytes: int) -> int:
    """Conservative V2 bound for distinct Binary64 vectors and metadata.

    V2 stores every value as exactly sixteen hexadecimal bytes.  The bound is
    intentionally independent of a value's decimal or ``float.hex`` spelling.
    """
    if type(frame_count) is not int or type(record_metadata_bytes) is not int or frame_count < 0 or record_metadata_bytes < 0:
        raise ValueError("RECORD_ESTIMATE_INVALID")
    # JSON string quotes and a comma need at most eighteen bytes per 16-byte
    # Binary64 token.  Keep one extra byte per token as a structural margin.
    vector_bytes = frame_count * (48 * 19 + len('{"values_bits":[]}'))
    frame_bytes = frame_count * (64 + 64 + 64 + 64 + 32 + len('{"ordinal":,"owner":"","profile":"","segment":"","vector":}'))
    return len('{"frames":[],"record":,"vectors":[],"version":"s2uc.record-codec.v3"}') + vector_bytes + frame_bytes + record_metadata_bytes


def record_metadata_bytes(data: bytes) -> int:
    """Return the serialized non-table record payload size for preflight limits."""
    value = json.loads(data)
    if type(value) is not dict or value.get("version") not in {PREVIOUS_VERSION, VERSION} or "record" not in value:
        raise ValueError("RECORD_CODEC_INVALID")
    return len(json.dumps(value["record"], allow_nan=False, sort_keys=True, separators=(",", ":")).encode("utf-8"))


def conservative_metadata_ceiling(*, record_limit: int, frame_count: int) -> int:
    """Largest metadata payload that remains safe even with distinct frame vectors."""
    baseline = estimate_worst_case(frame_count=frame_count, record_metadata_bytes=0)
    if type(record_limit) is not int or record_limit < baseline:
        raise ValueError("RECORD_ESTIMATE_INVALID")
    return record_limit - baseline

